// Clumsy, error-prone tagged class!
public class Figure {
    enum Shape { RECTANGLE, CIRCLE };

    // Tag field
    final Shape shape;

    // Fields used only for RECTANGLE
    double length;
    double width;

    // Field used only for CIRCLE
    double radius;

    // Constructor for circle
    Figure(double radius) {
        shape = Shape.CIRCLE;
        this.radius = radius;
    }

    // Constructor for rectangle
    Figure(double length, double width) {
        shape = Shape.RECTANGLE;
        this.length = length;
        this.width = width;
    }

    double area() {
        switch(shape) {
            case RECTANGLE: return length * width;
            case CIRCLE:    return Math.PI * (radius * radius);
            default: throw new AssertionError(shape);
        }
    }
}

